        'uExtent',
        'uMargin',
        'uRatio',
        'uCosine',
        'uSine',
        'uDensity',
        'uWidth',
        'uOpacity',
        'uDashLength',
        'uDashGap',
        'uStyle',
        'uLevelOffset',
        'uLayers[0]',
        'uLineColor',
        'uAccentColor',
        'uGradientEnabled',
        'uGradientStops',
        'uGradientDiffusion',
        'uGradientColors[0]',
        'uStamps[0]',
        'uStampCount',
