/* Omitted Paper colors follow an explicit site theme, then the system theme. */
.topographic-flow {
  --topographic-flow-background: #ffffff;
  --topographic-flow-ink: #000000;
}
:root[data-theme='dark'] .topographic-flow,
.dark .topographic-flow {
  --topographic-flow-background: #000000;
  --topographic-flow-ink: #ffffff;
}
:root[data-theme='light'] .topographic-flow {
  --topographic-flow-background: #ffffff;
  --topographic-flow-ink: #000000;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']):not([data-theme='dark']) .topographic-flow {
    --topographic-flow-background: #000000;
    --topographic-flow-ink: #ffffff;
  }
}
.topographic-flow {
  position: relative;
  isolation: isolate;
  width: 100%;
  height: 100%;
  overflow: hidden;
}
.topographic-flow-canvas {
  position: absolute;
  z-index: 1;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}
.topographic-flow-content {
  position: relative;
  z-index: 3;
  min-height: 100%;
}
